266	  let x = -9999, y = -9999, queued = false;
267	  const reach = 140;
268	  // One light source, above and to the left of the pointer. An entity reflects it only on the
269	  // edge that faces it most directly, at the point on that edge nearest the pointer.
270	  const source = { dx: -120, dy: -220 };
271	  const reflection = r => {
272	    const sx = x + source.dx, sy = y + source.dy;
273	    const cx = Math.min(Math.max(x, r.left), r.right), cy = Math.min(Math.max(y, r.top), r.bottom);
274	    const edges = [
275	      sy < r.top && { px: cx, py: r.top, nx: 0, ny: -1 },
276	      sy > r.bottom && { px: cx, py: r.bottom, nx: 0, ny: 1 },
277	      sx < r.left && { px: r.left, py: cy, nx: -1, ny: 0 },
278	      sx > r.right && { px: r.right, py: cy, nx: 1, ny: 0 },
279	    ].filter(Boolean);
280	    let best = null;
281	    for (const e of edges) {
282	      const lx = sx - e.px, ly = sy - e.py, facing = (lx * e.nx + ly * e.ny) / Math.hypot(lx, ly);
283	      const d = Math.hypot(x - e.px, y - e.py);
284	      const strength = d < reach ? facing * (1 - d / reach) ** 1.5 : 0;
285	      if (strength > (best ? best.strength : 0)) best = { ...e, strength };
286	    }
287	    return best;
288	  };
289	  // The reflection is drawn in each entity's lit edge, so it stays on the outline.
290	  const reflect = rects => {
291	    const hits = rects.map((r, i) => ({ i, h: reflection(r) })).filter(o => o.h)
292	      .sort((a, b) => b.h.strength - a.h.strength).slice(0, 6);
293	    lit.forEach(el => el.style.setProperty('--gs', 0));
294	    for (const { i, h } of hits) {
295	      lit[i].style.setProperty('--gx', h.px - rects[i].left + 'px');
296	      lit[i].style.setProperty('--gy', h.py - rects[i].top + 'px');
297	      lit[i].style.setProperty('--gs', h.strength.toFixed(3));
298	    }
299	  };
300	  const paint = () => {
301	    queued = false;
302	    const rects = lit.map(el => el.getBoundingClientRect());
303	    spot.style.setProperty('--x', x + 'px');
304	    spot.style.setProperty('--y', y + 'px');
305	    lit.forEach((el, i) => {
306	      el.style.setProperty('--mx', x - rects[i].left + 'px');
307	      el.style.setProperty('--my', y - rects[i].top + 'px');
308	    });
309	    reflect(rects);
310	  };
311	  const queue = () => { if (!queued) { queued = true; requestAnimationFrame(paint); } };
312	  addEventListener('pointermove', e => { x = e.clientX; y = e.clientY; spot.classList.add('on'); queue(); });
313	  addEventListener('scroll', queue, { passive: true });
314	  document.addEventListener('pointerleave', () => { spot.classList.remove('on'); x = y = -9999; queue(); });
