        }
    }

    #[test]
    fn each_subscription_is_asked_its_own_way_and_a_key_provider_is_left_alone() {
        let engine = FakeEngine::new(Link::Up)
            .answer(
                "provider::openai-codex::auth::status",
                Ok(json!({ "status": "authenticated" })),
            )
            .answer("router::models::list", Ok(json!({ "models": [] })));
        let codex = crate::rt::block_on(with_sign_in(&engine, view("openai-codex")));
        assert_eq!(codex.source, "signed_in");
        let claude = crate::rt::block_on(with_sign_in(&engine, view("claude-code")));
        assert_eq!(claude.source, "none", "no models means no sign-in");
        let mut deepseek = view("deepseek");
        deepseek.source = "secret".into();
        let kept = crate::rt::block_on(with_sign_in(&engine, deepseek.clone()));
        assert_eq!(kept, deepseek);
    }

    #[test]
    fn a_finished_sign_in_reads_the_models_again() {
        let engine = FakeEngine::new(Link::Up)
            .answer(
                "provider::openai-codex::login::poll",
                Ok(json!({ "status": "ok" })),
            )
            .answer(
                "provider::openai-codex::refresh_models",
                Ok(json!({ "count": 3 })),
            );
        let status = crate::rt::block_on(codex_sign_in_poll(&engine, "l1".into()));
        assert_eq!(status, Ok("ok".into()));
        assert!(engine.called("provider::openai-codex::refresh_models"));
    }
}
/// `configuration::set` replaces the whole value (N13).
async fn point(engine: &dyn Engine, id: &str, reference: Option<String>) -> Result<(), String> {
    let get = json!({ "id": ROUTER_ENTRY, "raw": true });
    let current = engine.call("default", "configuration::get", get).await?;
    let value = with_key(current["value"].clone(), id, reference);
    let set = json!({ "id": ROUTER_ENTRY, "value": value });
    engine
        .call("default", "configuration::set", set)
        .await
        .map(|_| ())
}

/// The vault name of provider `id`'s key (`deepseek` keeps
/// `DEEPSEEK_API_KEY`), or a refusal for a provider the router does not
/// know, so a typo makes no secret.
async fn known(engine: &dyn Engine, id: &str) -> Result<String, String> {
    let all = providers(engine).await?;
    let Some(p) = all.iter().find(|p| p.id == id) else {
        return Err(format!("no model provider {id}"));
    };
    if p.source == "signed_in" || matches!(id, "openai-codex" | "claude-code") {
        return Err(format!(
            "{} signs in with a subscription, not a key",
            p.name
        ));
    }
    Ok(format!("{}_API_KEY", id.to_uppercase().replace('-', "_")))
}

